INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Event-Listener immer an ein DOM-Element gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch globale Events möglich"}, {"text": "Ja", "correct": false, "because": "Nicht auf DOM beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Event-Listenern in meiner UI?', 3, '[{"text": "Interaktivität", "correct": true, "because": "Reagiert auf Nutzeraktionen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht relevant"}, {"text": "Schnelle Builds", "correct": false, "because": "Pipeline-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Event-Listenern und -Handlern?', 5, '[{"text": "Event-Typ", "correct": true, "because": "Definiert Auslöser wie Klick"}, {"text": "Handler-Funktion", "correct": true, "because": "Reaktion auf Event"}, {"text": "Farbanimation", "correct": false, "because": "Kein Ereignisaspekt"}, {"text": "Statische Daten", "correct": false, "because": "Dynamik im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Listener kann mehrere Handler haben. b) Handler sind immer asynchron.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Handler meist synchron"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Event-Listenern?', 4, '[{"text": "Event-Propagation", "correct": false, "because": "Beeinflusst Verhalten"}, {"text": "Handler-Logik", "correct": false, "because": "Definiert Reaktion"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Ereignisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Event-Listener auch entfernt werden kann?', 2, '[{"text": "Ja", "correct": true, "because": "Mit removeEventListener möglich"}, {"text": "Nein", "correct": false, "because": "Entfernung wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Event-Typ wähle ich für einen Mausklick?', 3, '[{"text": "click", "correct": true, "because": "Standard für Klicks"}, {"text": "mouseover", "correct": false, "because": "Nur bei Hover"}, {"text": "keydown", "correct": false, "because": "Tastatureingabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen Event-Handler effektiv?', 5, '[{"text": "Spezifische Events", "correct": true, "because": "Präzise Reaktion"}, {"text": "Effiziente Logik", "correct": true, "because": "Schnelle Ausführung"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Ereignisaspekt"}, {"text": "Statische Layouts", "correct": false, "because": "Dynamik zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Event-Listener sind nur für UI wichtig. b) Handler können Events stoppen. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Listener auch außerhalb UI"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Event-Listener?', 4, '[{"text": "Event-Typ", "correct": false, "because": "Definiert Auslöser"}, {"text": "Callback-Funktion", "correct": false, "because": "Reagiert auf Event"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Ereignisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'How war das nochmal? Sind Event-Listener nur für Klicks da?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Eingaben, Scrollen etc."}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden steuern Event-Propagation?', 4, '[{"text": "stopPropagation", "correct": true, "because": "Stoppt Weiterleitung"}, {"text": "preventDefault", "correct": true, "because": "Verhindert Standardaktion"}, {"text": "resizeWindow", "correct": false, "because": "Kein Event-Steuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Event-Handler immer synchron laufen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Standard in JS"}, {"text": "Nein", "correct": false, "because": "Asynchron nur mit Promises"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Event-Handler für Klicks?', 3, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Nutzererlebnis zählt"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Sekundär"}, {"text": "Einfache Farben", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Listener können Events abfangen. b) Handler sind nur für Mausaktionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Handler für alles"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Events verbessern die UI-Interaktivität?', 5, '[{"text": "click", "correct": true, "because": "Reagiert auf Klicks"}, {"text": "input", "correct": true, "because": "Erfasst Eingaben"}, {"text": "resize", "correct": false, "because": "Nur Fensteränderung"}, {"text": "load", "correct": false, "because": "Nur Initialisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Event-Listenern unwichtig?', 3, '[{"text": "Event-Typ", "correct": false, "because": "Definiert Auslöser"}, {"text": "Handler-Logik", "correct": false, "because": "Reaktion zählt"}, {"text": "Blinkende Icons", "correct": true, "because": "Kein Ereignisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Listener mehrere Events abonnieren?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrere Typen möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob preventDefault die Weiterleitung stoppt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Standardaktionen"}, {"text": "Ja", "correct": false, "because": "stopPropagation für Weiterleitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Event-Handler wähle ich für eine Eingabevalidierung?', 4, '[{"text": "input", "correct": true, "because": "Erfasst Eingaben live"}, {"text": "click", "correct": false, "because": "Nur für Klicks"}, {"text": "mouseover", "correct": false, "because": "Nur für Hover"}]');
